story=[]
class ContentsLine(Flowable):
    def __init__(self,title,number):
        Flowable.__init__(self)
        self.title=title;self.number=str(number);self.width=WIDTH;self.height=16
    def draw(self):
        c=self.canv;c.setFont('TimesRU',10)
        c.drawString(0,4,self.title);c.drawRightString(self.width,4,self.number)
        left=pdfmetrics.stringWidth(self.title,'TimesRU',10)+7
        c.setStrokeColor(colors.HexColor('#888888'));c.setLineWidth(.4);c.setDash(1,2)
        c.line(left,5,self.width-18,5);c.setDash()
def p(text,style='body'):return Paragraph(text,styles[style])
def add(text):story.append(p(text))
def h(text):story.append(p(text,'h2'))
def page(title):
    if story:story.append(PageBreak())
    story.append(p(title,'h1'))
def table(headers,rows,widths):
    data=[[p(escape(t),'head') for t in headers]]+[[p(str(t),'cell') for t in row] for row in rows]
    t=Table(data,colWidths=[WIDTH*x for x in widths],repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e7edf2')),('GRID',(0,0),(-1,-1),.45,colors.HexColor('#b8c1c9')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
    story.extend([t,Spacer(1,9)])
def figure(name,width,caption):
    image=Image(str(ASSETS/name));ratio=image.imageHeight/image.imageWidth
    image.drawWidth=width;image.drawHeight=width*ratio
    story.extend([image,p(caption,'caption')])
def steps(items):
    for i,text in enumerate(items,1):story.append(p(f'<b>{i}.</b> {text}'))

