class ExampleChart(Flowable):
    def __init__(self):
        Flowable.__init__(self)
        self.width=WIDTH;self.height=145
    def draw(self):
        c=self.canv;left=35;bottom=24;w=self.width-48;hh=100
        c.setFont('TimesRU',9);c.setStrokeColor(colors.HexColor('#d0d0d0'))
        for temp in (50,150,250):
            y=bottom+(temp-30)/250*hh;c.line(left,y,left+w,y);c.setFillColor(GRAY);c.drawRightString(left-5,y-3,str(temp)+'°')
        planned=[(0,50),(.25,150),(.4,150),(.65,260),(.75,260),(1,100)]
        actual=[(0,55),(.25,148),(.4,151),(.65,256),(.75,261),(1,103)]
        for values,color,lw in [(planned,'#4caa59',2),(actual,'#ee9f32',3.5)]:
            c.setStrokeColor(colors.HexColor(color));c.setLineWidth(lw);path=c.beginPath()
            for i,(x,t) in enumerate(values):
                a=left+x*w;b=bottom+(t-30)/250*hh
                if i:path.lineTo(a,b)
                else:path.moveTo(a,b)
            c.drawPath(path)
        c.setFillColor(GRAY);c.drawString(left,8,'0 с');c.drawRightString(left+w,8,'Время профиля')

