def furniture(c,doc):
    c.saveState()
    c.setTitle(f'Меркурий 300, 301, 400, 401 Руководство ПО {VERSION}')
    c.setAuthor('Mercury')
    if doc.page>1:
        c.setFont('TimesRU',9);c.setFillColor(GRAY)
        c.drawString(20*mm,A4[1]-12*mm,'Меркурий 300 / 301 / 400 / 401')
        c.drawRightString(A4[0]-20*mm,A4[1]-12*mm,f'ПО {VERSION}')
        c.setStrokeColor(colors.HexColor('#b5b5b5'));c.setLineWidth(.4);c.line(20*mm,A4[1]-15*mm,A4[0]-20*mm,A4[1]-15*mm)
        c.drawString(20*mm,11*mm,'Руководство по эксплуатации программного обеспечения')
        c.drawRightString(A4[0]-20*mm,11*mm,str(doc.page))
    c.restoreState()

